 assert set(masks)==expected,(t,set(masks),expected)
 coverage.append({'case':t+' decision domain','sample_refs':['samples.json']+(['prior/samples.json'] if prior else []),'result':f'{len(records)} fresh and {len(prior)} prior independently sampled records; all {len(expected)} eligible masks represented: {dict(masks)}. Prior evidence applies only to unchanged construction; restored profile is entirely fresh.'})
