# Independently defined simple response-producing probes, before/after filters.
probes=[]
def baseline(rows):
 return sum(1/5 if visible(r)['radio'] else 1/(8 if len(r['question'][':question/answer-fields'])==4 else 7) for r in rows)/len(rows)
def add(cue,sub,scope,strategy,k,rows,ref,explanation,disposition='not_predictive',base=None):
 probes.append({'cue':cue,'subgroup':sub,'scope':scope,'strategy':strategy,'correct':int(k),'total':len(rows),'baseline':baseline(rows) if base is None else base,'disposition':disposition,'conclusion':explanation,'sample_refs':ref})
def cue_only(r):return all((correct(f)=='true')==('invertible' in f[':answer-field/key']) for f in r['question'][':question/answer-fields'])
def full_response(r):
 fs=r['question'][':question/answer-fields']
 return correct(fs[0]) if visible(r)['radio'] else ''.join('1' if correct(f)=='true' else '0' for f in fs)
for stage,rows,ref in [('fresh sampler',raw,'samples.json'),('delivery survivors',accepted,'delivery-samples/accepted.json'),('pre-rejection',candidates,'sampling-candidates.json'),('post-rejection',cycle,'sampling-cycle.json'),('post-rejection delivered',delcycle,'delivery-cycle/accepted.json')]:
 groups=collections.defaultdict(list)
 for r in rows:
  groups[r['generation']['template']].append(r)
  groups[r['generation']['template']+'/'+visible(r)['kind']].append(r)
 for name,sub in groups.items():
  c=collections.Counter(visible(r)['mask'] for r in sub);mask,count=c.most_common(1)[0]
  add('template identity'+(' and given kind' if '/' in name else ''),stage+': '+name,'within_template',f'Always choose statements with mask {mask} in statement order',count,sub,[ref],f'Best fixed subset succeeds {count}/{len(sub)}. Comparison baseline is uniform over the five source radio-bank subsets, seven nonempty checkbox subsets, or eight source-backed None states. Small singleton subgroups cannot establish repetition; no family-wide fixed subset in the combined source-grounded coverage.')
  if not visible(sub[0])['radio']:
   k=sum(map(cue_only,sub));add('invertibility wording',stage+': '+name,'within_template','Select only the claim containing invertible, ignoring given data',k,sub,[ref],f'Full response success {k}/{len(sub)}; baseline as above. This cue has counterexamples in every complete checkbox profile in the combined independent controls.')
