add('actual radio display position','exact delivered batch, radio controls','other_recognizable_subgroup','Always choose displayed position '+str(pos),k,radios,['ui-radio-order.json','render-records.json'],'Actual positions are '+str([x['correct_position_1_based'] for x in ui])+'. Best fixed display position succeeds 1/2 versus uniform 1/5; generator raw bank index is not assumed to be displayed index.',base=.2)
sub=[r for r in raw if visible(r)['kind']=='nonzero-vector']
