add('nonzero homogeneous witness','all nonzero-vector templates','other_recognizable_subgroup','Infer singularity from Av=0 and v nonzero',len(sub),sub,['samples.json'],'This mathematical inference is taught in tutorial 3522 and is the intended first stage. It does not identify the full true subset without reading each varied claim. Binary status-guess baseline is 1/2.',disposition='intended_skill',base=.5)
