def choose(ids,seed,positive=True,configured=True):
 ids=sorted(set(ids))
 if not ids:return None
 if not configured:return ids[0]
 if not positive:return None
 d=hashlib.sha256(('course-academy/question-selection/v1/'+seed).encode()).digest();u=(int.from_bytes(d[8:16],'big')>>11)/(1<<53)
 return ids[int(u*len(ids))]
scenarios=[]
for seen in [[],[1],[2],[1,2,3]]:
 eligible=[i for i in range(1,len(batch)+1) if i not in seen]
 draws=collections.Counter(choose(eligible,str(s)) for s in range(1000))
 scenarios.append({'seen_surrogate_ids':seen,'eligible_surrogate_ids':eligible,'configured_positive_moderate_draws':dict(draws),'legacy_unconfigured_choice':choose(eligible,'',configured=False),'zero_moderate_weight_choice':choose(eligible,'',positive=False)})
